const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = +data[0];
const a = data.slice(1, 1 + n).map(Number);

// Um corte na altura h divide o papel em (número de runs de retângulos com Ai >= h) pedaços
// acima do corte + 1 pedaço abaixo (sempre conectado pela base em y ∈ [0,1), pois Ai >= 1).
// Maximizamos o número de runs sobre todas as alturas possíveis (thresholds iguais às alturas).

const idx = Array.from({ length: n }, (_, i) => i).sort((x, y) => a[y] - a[x]);
const active = new Uint8Array(n);
let comp = 0, best = 0;

for (let k = 0; k < n; k++) {
  const i = idx[k];
  comp++;
  if (i > 0 && active[i - 1]) comp--;
  if (i < n - 1 && active[i + 1]) comp--;
  active[i] = 1;
  // só registramos o número de componentes quando a batch de altura igual termina
  if (k === n - 1 || a[idx[k + 1]] !== a[i]) {
    if (comp > best) best = comp;
  }
}

console.log(best + 1);
